// v16.xx, the raid text voice, his order of 2026-10-09 (raid lines read like a shooter HUD): BACKPACK FULL, with the key that
// drops an item as its detail (the pad's own drop button, Y in the backpack, on a pad), or with autoloot on, the count and
// that nothing in it may be dropped. v21.91 (R07): said every frame E is held, so it refreshes its row (key bagfull).
say('BACKPACK FULL','info',{key:'bagfull',sub:P.autoloot?(cap+'/'+cap+'  \u00b7  Nothing to drop'):('['+(padOn()?padB('Y'):keyLabel('KeyZ','Z'))+'] Drop selected item')});

// v16.xx, the raid text voice: the teammate's call as a headline (you call FOR extraction), the ring and the time as its detail.
var _bn=netSeatName(peer.seat), _bi=Math.ceil(Z.beaconT);
blip('beacon'); say((_bn?String(_bn).toUpperCase():'TEAMMATE')+' CALLED FOR EXTRACTION','info',{sub:'Extraction '+extLetter(Z)+'  \u00b7  Inbound '+(_bi<60?_bi+'s':fmtClock(_bi))});

