{v:'VER',what:'the raid text voice after the queue: BACKPACK FULL with the drop key or Nothing to drop, NAME DOWN with Hold [E] to revive, NAME IS SEARCHING, and none of the old sentences (Stay alive, He will shoot on sight, Pick them up) is left in the game',
 run:function(){
   if(!(window.__deploy&&window.__state&&window.__endRaid&&window.__loop)) return 'SKIP: this fixture cannot deploy or step the loop';
   if(window.__vpAlive&&!__vpAlive()) return 'SKIP: the pane has no layout, so the frame loop cannot draw';
   if(typeof netOnState!=='function'||typeof netSrchHold!=='function'||typeof NET!=='object'||!NET||typeof bagWeight!=='function') return 'SKIP: no party words or no backpack weight here';
   var NK={}, k, bad=[], g, p, realSay=say, realSwf=sayWhenFree, oRum=padRumble, oName=netSeatName, keepBW=bagWeight, keepAuto=P.autoloot, peer={seat:1,state:'in'}, w, t0, f=0, i, said=[], box=null, src='', olds, sc, gs, last;
   function step(){ __loop(t0+(++f)*16.7); }
   function shape(e,what){
     if(!e){ bad.push(what+' said nothing'); return; }
     if(e.m.length>34||e.m!==e.m.toUpperCase()||/[.!?:]$/.test(e.m)) bad.push(what+' headline '+JSON.stringify(e.m)+' is not a caps headline of 34 or fewer with no end punctuation');
     if(e.sub&&e.sub.length>48) bad.push(what+' detail '+JSON.stringify(e.sub)+' is longer than 48');
   }
   function lastOf(rx){ for(var j=said.length-1;j>=0;j--) if(rx.test(said[j].m)) return said[j]; return null; }
   for(k in NET) NK[k]=NET[k];
   try{
     // ONE: the old sentences are gone from the game script
     sc=[].slice.call(document.scripts);
     for(i=0;i<sc.length;i++) if((sc[i].text||'').indexOf('function msgRow'+'Text(')>=0) src+=sc[i].text;
     if(!src) bad.push('SKIP: the game script was not found');
     olds=[' is down. Pick them '+'up.','He will shoot on '+'sight','Stay '+'alive.','called extraction. '+'Inbound in','nothing left worth '+'dropping','Z drops the selected '+'item','is searching this '+'one.',"say('Zo"+"om '","say('Zo"+"om 100"];
     for(i=0;src&&i<olds.length;i++) if(src.indexOf(olds[i])>=0) bad.push('the game still says '+JSON.stringify(olds[i]));
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     try{ __pinDPR(1); }catch(_d){}
     NET.on=false; NET.role=null; NET.peers=[];
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); if(!g||g.over||!g.player) return 'SKIP: staging: no raid';
     p=g.player; keys={}; g.mapOpen=false; g.bagOpen=false; g.ents.length=0; g.waveT=-1e9;
     say=function(m,kd,o){ said.push({m:String(m),k:kd,sub:(o&&o.sub)?String(o.sub):''}); };
     sayWhenFree=function(m,kd,o){ said.push({m:String(m),k:kd,sub:(o&&o.sub)?String(o.sub):''}); };
     padRumble=function(){ return 'test'; };
     netSeatName=function(s){ return s===1?'Moth':(s===0?'Host':null); };
     t0=performance.now();
     // TWO, THE PLAY PATH: X held on a box with the backpack full, autoloot off and then on
     for(i=0;i<g.containers.length;i++){ var c=g.containers[i]; if(c&&!c.opened&&c.loot&&c.loot.length&&!c.cache&&!c.strong&&!c.auto){ box=c; break; } }
     if(!box) bad.push('SKIP: no box to stage the full backpack on');
     else {
       box.x=p.x+20; box.y=p.y; box.opened=false; box.prog=0; p.downed=false;
       bagWeight=function(){ return 1e9; };
       P.autoloot=0; keys['KeyX']=true; for(i=0;i<6;i++){ step(); if(g.over) break; } keys={};
       last=lastOf(/^backpack full/i); shape(last,'a full backpack');
       if(last&&(last.m!==['BACKPACK','FULL'].join(' ')||last.sub!=='['+keyLabel('KeyZ','Z')+'] Drop selected item')) bad.push('a full backpack says '+JSON.stringify(last.m)+' / '+JSON.stringify(last.sub)+', not BACKPACK FULL with the drop key');
       said.length=0; P.autoloot=1; keys['KeyX']=true; for(i=0;i<6;i++){ step(); if(g.over) break; } keys={};
       last=lastOf(/^backpack full/i); shape(last,'a full backpack with autoloot');
       if(last&&last.sub.indexOf('Nothing to drop')<0) bad.push('a full backpack with autoloot says '+JSON.stringify(last.sub)+' as its detail, not Nothing to drop');
       bagWeight=keepBW; P.autoloot=keepAuto;
     }
     // THREE: a teammate down, on the word that first carries the flag
     said.length=0;
     NET.on=true; NET.role='host'; NET.seat=0; NET.max=4; NET.peers=[peer]; NET.up=[]; NET.floor=NET.floor||[];
     w={t:'st',k:'r',x:Math.round(p.x)+60,y:Math.round(p.y),f:0,sd:g.seed>>>0,dn:0,hp:100,mh:100};
     netOnState(peer,w); netOnState(peer,w); w.dn=1; netOnState(peer,w);
     last=lastOf(/MOTH/i); shape(last,'a teammate down');
     if(last&&(last.m!=='MOTH DOWN'||last.sub!=='Hold ['+keyLabel('KeyE','E')+'] to revive'||last.k!=='crit')) bad.push('a teammate down says '+JSON.stringify(last.m)+' / '+JSON.stringify(last.sub)+' as '+last.k+', not MOTH DOWN / Hold [E] to revive as crit');
     // FOUR: a box a teammate holds, on the host
     said.length=0;
     if(box){ box.netBy=1; box.netSaidT=undefined; gs=g.searching; netSrchHold(box,0.016); g.searching=gs; delete box.netBy; delete box.netSaidT; }
     last=lastOf(/SEARCHING/i); shape(last,'a box a teammate holds');
     if(box&&last&&last.m!=='MOTH IS SEARCHING') bad.push('a box a teammate holds says '+JSON.stringify(last.m)+', not MOTH IS SEARCHING');
   }catch(err){ bad.push('threw: '+(err&&err.message||err)); }
   finally{
     say=realSay; sayWhenFree=realSwf; padRumble=oRum; netSeatName=oName; bagWeight=keepBW; P.autoloot=keepAuto; keys={};
     for(k in NET) if(!(k in NK)) delete NET[k];
     for(k in NK) NET[k]=NK[k];
     try{ var g2=__state(); if(g2){ g2.msgT=0; g2.msg=''; g2.feed=[]; g2.msgQ=[]; g2.msgQM=[]; g2.msgKey=''; } if(g2&&!g2.over){ g2.player.downed=false; g2.searching=null; __endRaid('abandon'); } }catch(_e){}
     __topClear();
   }
   for(i=0;i<bad.length;i++) if(bad[i].indexOf('SKIP: ')===0&&bad.length===1) return bad[0];
   return bad.length?bad.join('; '):null; }},
